{
  "name": "rf_cob_state_machine",
  "confidence": "medium",
  "docstring": "Advances the RF COB state machine by handling the enabled state-2 transition, computing and storing COB table values, logging the state change, and otherwise resetting or post-processing the COB context.",
  "subsystem": "rf",
  "var_renames": {
    "v0": "cob_enable_flag",
    "v1": "cob_state_ptr",
    "v2": "cob_entry_count_ptr",
    "v3": "cob_entry_table_ptr",
    "v4": "last_entry_index",
    "v5": "cob_last_entry_ptr",
    "v6": "cob_entry_byte_offset",
    "v18": "cob_last_entry_ptr",
    "v25": "cob_entry_table_ptr"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "COB context state byte (first byte of object referenced by off_126734); the COB table pointer may also expose a 16-bit field at the first entry offset."
    },
    {
      "offset": 2,
      "meaning": "COB table entry byte offset 2: u8 field used as a divisor/scale in the non-enabled processing path."
    },
    {
      "offset": 4,
      "meaning": "COB table entry byte offset 4: result byte written during entry processing in the non-enabled path."
    },
    {
      "offset": 5,
      "meaning": "COB table entry byte offset 5: result byte written for the first entry during the state-2 completion path."
    }
  ]
}
